from lib import *
N=3
TITLE='מעמד חוקי היסוד ושריון'
SUM=[
h3('3.1 מהו חוק יסוד ומה מעמדו'),
p('בהיררכיה הנורמטיבית בישראל חוק יסוד נמצא מעל החוק הרגיל. חוק רגיל שסותר חוק יסוד, שלא בהתאם לפסקת ההגבלה, אינו תקף. לפי בנק המזרחי מקור העליונות הוא <b>הסמכות המכוננת</b> של הכנסת. כדי לדעת מהו חוק יסוד נעשה שימוש ב<b>מבחן צורני</b>: חוק הנקרא "חוק יסוד: ..." (בלי ציון שנה בשם) הוא חוק יסוד, והכותרת מסמנת את כוונת הכנסת לפעול בכובע המכונן. המבחן הצורני מונע התדיינות על כל חוק שנחשב חשוב מהותית, אך מותיר את השאלה אם הכנסת רשאית לכנות כל דבר "חוק יסוד" (בלי להפר גבולות).'),
box('def','היררכיית הנורמות','חוק יסוד ← חוק רגיל ← חקיקת משנה (תקנות) ← החלטה מנהלית. כל נורמה נבחנת מול הנורמה שמעליה, וחוק רגיל נבחן גם מול חוק היסוד.'),
h3('3.2 שריון: הגנה על חוק היסוד מפני שינוי'),
p('<b>שריון</b> הוא מנגנון המקשה על שינוי הוראה בחוק יסוד, ובכך מבטא נוקשות חוקתית. קיימים כמה סוגי שריון. <b>שריון פורמלי</b> דורש רוב מיוחד לשינוי ההוראה (למשל רוב של חברי הכנסת, 61, ובמקרים חריגים 80). <b>שריון עניני (מהותי)</b> מחייב שהשינוי ייעשה בחוק יסוד, ולא בחוק רגיל. דוגמה מובהקת: ס׳ 4 לחוק יסוד: הכנסת (עקרון השוויון בבחירות) משוריין ברוב של חברי הכנסת. בחוק יסוד: חופש העיסוק יש הוראת שריון ברוב של חברי הכנסת, ובחוק יסוד: כבוד האדם עצמו אין שריון כללי של תוכן הזכויות.'),
tbl(['סוג שריון','מה נדרש לשינוי','דוגמה'],[
['פורמלי','רוב מיוחד של חברי הכנסת (61 או 80)','ס׳ 4 לחוק יסוד: הכנסת'],
['עניני (מהותי)','שינוי רק בחוק יסוד, לא בחוק רגיל','הוראות המפנות לתיקון "בחוק יסוד"'],
['ללא שריון','תיקון בחוק יסוד ברוב רגיל (אך רק בחוק יסוד)','חלק מחוקי היסוד, כגון כבוד האדם']]),
box('case','ברגמן נ׳ שר האוצר (1969)','חוק מימון מפלגות נתקבל ברוב רגיל, אף שהוראת השוויון בבחירות משוריינת. נקבע שחוק שנחקק בניגוד לשריון בטל. ההלכה היא שהכנסת כבולה בהוראות שריון, גם כשמדובר בשינוי עקיף של ההוראה המשוריינת.'),
h3('3.3 הבחנה: שינוי חוק יסוד לעומת פגיעה בזכות'),
p('<b>שינוי</b> חוק יסוד פירושו תיקון נוסחו. אם הוא משוריין - נדרש הרוב הנדרש. <b>פגיעה</b> בזכות פירושה חוק רגיל שפוגע בזכות המעוגנת בחוק היסוד, מבלי לשנות אותו. פגיעה כזו נבחנת בפסקת ההגבלה (פרק 4). ההבחנה חשובה כי לא כל חוק הפוגע בזכות "משנה" חוק יסוד, ולכן אין צורך ברוב מיוחד לכל חוק רגיל שפוגע בזכות. אך הוראת שריון עצמה מחייבת את הכנסת בדרך שבה היא משנה אותה.'),
h3('3.4 שמירת דינים'),
p('ס׳ 10 לחוק יסוד: כבוד האדם וחירותו מורה ש"אין בחוק-יסוד זה כדי לפגוע בתקפו של דין שהיה קיים ערב תחילתו". כלומר חקיקה שנחקקה לפני מרץ 1992 אינה ניתנת לפסילה בשל סתירה לחוק היסוד. אולם בית המשפט פירש זאת בצמצום: חקיקה ישנה <b>נפרשת</b> לאור ערכי היסוד החדשים, ושינוי מהותי או תיקון מאוחר לחוק ישן אינו מוגן. פסקת שמירת הדינים נועדה למנוע פתיחה מחדש של כל חקיקת "דת ומדינה" הקיימת.'),
box('law','ס׳ 10 לחוק יסוד: כבוד האדם וחירותו','שמירת תוקפם של דינים שקדמו לחוק היסוד. אינה חלה על חקיקה חדשה, ואינה אוסרת פרשנות מחודשת של הדין הישן.'),
h3('3.5 גבולות הסמכות המכוננת'),
p('שאלה פתוחה היא אם יש גבול לכוח המכונן של הכנסת. בפסיקה התפתחה הדוקטרינה של <b>שימוש לרעה בסמכות מכוננת</b>: בג"ץ הציע כי חוק יסוד שפוגע בגרעין הזהות החוקתית (אופי יהודי ודמוקרטי, שלטון חוק, זכויות יסוד) עלול להיפסל. בשנת 2020 דן בית המשפט בעתירות נגד חוקי יסוד שהסדירו ממשלת רוטציה, ודחה אותן אך קבע שבשימוש לרעה בסמכות ניתן להתערב. בשנת 2021 דחה בהרכב מורחב עתירות נגד חוק יסוד: הלאום. ב-2024 פסל בג"ץ (5658/23) תיקון לחוק יסוד: השפיטה, והכריע בעיקרון שיש לבית המשפט סמכות לבקר חוק יסוד במקרים קיצוניים.'),
box('warn','מלכודות נפוצות',['להניח שכל חוק יסוד משוריין - רבים אינם משוריינים.','לבלבל בין "פגיעה" ל"שינוי": הראשונה נבחנת בפסקת ההגבלה, השנייה בדרישת השריון.','לחשוב שחוק שנחקק לפני 1992 לעולם אינו ניתן לביקורת - הוא מוגן מפני פסילה, אך נפרש לאור חוק היסוד.']),
h3('3.6 שלד לפתרון שאלה בנושא'),
ol('האם הנורמה היא חוק יסוד או חוק רגיל (בדיקה צורנית)?','האם קיימת הוראת שריון, ומה סוגה?','האם החוק נתקבל ברוב הנדרש?','אם החוק רגיל והוא סותר חוק יסוד - האם נפגעה זכות ומה דינה בפסקת ההגבלה?','האם נדרשת שמירת דינים (חוק קדם ל-1992)?'),
box('ex','תרגיל פתור','הכנסת חוקקה ב-1996 תיקון לחוק מ-1960 שפוגע בקניין. האם ס׳ 10 מגן? <b>פתרון:</b> לא; התיקון חדש, ולכן אינו נהנה משמירת דינים ונבחן לפי פסקת ההגבלה. אילו החוק לא תוקן - היה מוגן מפני פסילה.'),
box('key','סיכום הפרק',['חוק יסוד עליון; חוק רגיל הסותר אותו (שלא כדין) בטל.','זיהוי חוק יסוד - מבחן צורני.','שריון: פורמלי (רוב מיוחד) ועניני (שינוי בחוק יסוד).','שינוי ≠ פגיעה.','ס׳ 10: שמירת דינים - ישן מוגן, חדש לא.','גבולות הסמכות המכוננת: שימוש לרעה; הלכת 5658/23.'])
]
CASES=[
('בג"ץ 98/69 ברגמן נ׳ שר האוצר (1969)','חוק מימון מפלגות נחקק ברוב רגיל על אף שריון ס׳ 4 לחוק יסוד: הכנסת.','הוראת שריון מחייבת את הכנסת. חוק שנחקק בניגוד לה, ללא הרוב הנדרש, אינו תקף. למבחן: דוגמה לשריון פורמלי ולביקורת על חוקיות הליך החקיקה.'),
('ע"א 6821/93 בנק המזרחי נ׳ מגדל כפר שיתופי (1995)','עתירה נגד חוק גל והשאלה מהו מעמד חוקי היסוד.','לחוק יסוד מעמד על-חוקי מכוח הסמכות המכוננת. מבחן צורני: כותרת "חוק יסוד". למבחן: הקשר בין עליונות חוק היסוד לבין שריון.'),
('בג"ץ 2605/05 המרכז האקדמי למשפט ולעסקים נ׳ שר האוצר (2009)','הפרטת בתי סוהר בחוק רגיל.','החוק נפסל כי פגע בכבוד ובחירות האסירים בניגוד לפסקת ההגבלה. למבחן: דוגמה לחוק חדש שאינו מוגן בשמירת דינים ונפסל בפועל.'),
('בג"ץ 5658/23 התנועה למען איכות השלטון נ׳ הכנסת (2024)','תיקון לחוק יסוד: השפיטה שצמצם את עילת הסבירות.','נפסל התיקון, וקביעה שבית המשפט רשאי לבקר חוק יסוד במקרים נדירים של שימוש לרעה בסמכות המכוננת. הסמכות לבקר חוק יסוד במקרים קיצוניים נקבעה ברוב של 12 מתוך 15 שופטים, והפסילה עצמה ברוב של 8 מול 7. למבחן: הלכת הגבלת הסמכות המכוננת.')
]
QS=[
Q('לפי המבחן הצורני, מהו חוק יסוד?','חוק שהכנסת קראה לו "חוק יסוד: ..." בלי ציון שנה',['כל חוק החשוב לכלל הציבור','חוק שנקבע על ידי בית המשפט','חוק שנתקבל ברוב של 80 חברי כנסת'],'המבחן הצורני נשען על שם החוק. חשיבות הציבור או רוב מיוחד אינם קריטריון, ובית המשפט אינו מחוקק חוקי יסוד, ולכן אלה אינם המבחן הצורני.'),
Q('מהו שריון פורמלי?','הצורך ברוב מיוחד כדי לשנות הוראה',['החובה לפרסם הוראה בעיתון','איסור מוחלט על שינוי','חובת שינוי בפסיקה'],'שריון פורמלי הוא דרישה לרוב מוגבר (למשל 61). איסור מוחלט אינו שריון רגיל, ופרסום או פסיקה אינם קשורים לשריון.'),
Q('איזו הוראה משוריינת במפורש בחוק יסוד: הכנסת?','עקרון השוויון בבחירות (ס׳ 4)',['חופש העיסוק','חופש הדת','חסינות שופטים'],'ס׳ 4 לחוק יסוד: הכנסת (בחירות כלליות, ארציות, ישירות, שוות, חשאיות ויחסיות) משוריין. חופש העיסוק וחופש הדת אינם בחוק היסוד, והחסינות אינה עניין לשריון זה.'),
Q('מה הרוב הנדרש לשינוי הוראה משוריינת בדרך כלל?','רוב של חברי הכנסת (61)',['רוב של 80','רוב של הנוכחים','פה אחד'],'ברוב ההוראות המשוריינות נדרש רוב מוחלט של חברי הכנסת (61). 80 נדרש רק במקרים מעטים (למשל הארכת כהונת הכנסת), ופה אחד אינו נדרש.'),
Q('מהו ההבדל בין "שינוי" חוק יסוד לבין "פגיעה" בזכות?','שינוי הוא תיקון נוסח חוק היסוד; פגיעה היא חוק רגיל הפוגע בזכות',['אין הבדל','פגיעה היא תיקון חוק יסוד; שינוי הוא ביקורת שיפוטית','שינוי הוא פסילה בידי בג"ץ'],'שינוי פירושו עריכת נוסח חוק היסוד ונדרש עבורו הרוב המתאים; פגיעה נבחנת לפי פסקת ההגבלה. ההיפך מההגדרות או זהות ביניהן אינם נכונים.'),
Q('מה קובע ס׳ 10 לחוק יסוד: כבוד האדם?','שמירת תוקפם של דינים שהיו קיימים לפני החוק',['איסור פגיעה בקניין','סמכות ביקורת שיפוטית','הרוב הנדרש לשינוי החוק'],'ס׳ 10 הוא פסקת שמירת דינים. איסור הפגיעה בקניין הוא ס׳ 3, והביקורת השיפוטית נגזרת מעליונות, לא מס׳ 10.'),
Q('חקיקה ישנה (לפני 1992) הנשמרת בס׳ 10:','אינה ניתנת לפסילה בשל חוק היסוד, אך נפרשת לאורו',['נפסלת אוטומטית','תקפה אך אינה ניתנת לפרשנות','פגה אחרי 4 שנים'],'חוק ישן מוגן מפסילה, אך הפרשנות מתעדכנת לפי ערכי היסוד. פסילה אוטומטית או פקיעה אינן הלכה.'),
Q('מה דינו של תיקון משנת 1996 לחוק מ-1960 הפוגע בקניין?','אינו מוגן בשמירת דינים ונבחן בפסקת ההגבלה',['מוגן בשמירת דינים','בטל בכל מקרה','תקף לארבע שנים'],'שמירת הדינים חלה על דין שהיה קיים ערב החוק, לא על תיקון חדש. לכן יש לבחון אותו בפסקת ההגבלה, ואין בטלות אוטומטית.'),
Q('מהי "פגיעה" במובן חוקתי?','חוק רגיל הפוגע בזכות מעוגנת בלי לשנות את חוק היסוד',['שינוי נוסח חוק יסוד','החלטה של שר','פסילת חוק'],'פגיעה היא חקיקה רגילה שמגבילה זכות. שינוי נוסח הוא שינוי ולא פגיעה, ופסילה היא סעד.'),
Q('בפרשת ברגמן הכנסת:','לא יכלה לשנות הוראה משוריינת ללא הרוב הנדרש',['רשאית לשנות כל הוראה ברוב רגיל','אינה כפופה לבג"ץ','חוקקה חוק יסוד חדש'],'ברגמן קבע כפיפות להוראת השריון, ולכן חוק שנתקבל בניגוד לה אינו תקף. הטענות האחרות מנוגדות להלכה.'),
Q('אילו מהבאים אינו חוק יסוד?','חוק החוזים (חלק כללי)',['חוק יסוד: הכנסת','חוק יסוד: ירושלים בירת ישראל','חוק יסוד: מבקר המדינה'],'חוק החוזים הוא חוק רגיל. שלושת האחרים הם חוקי יסוד לפי שמם.'),
Q('מהו "שריון עניני"?','החובה לשנות את ההוראה רק בחוק יסוד',['שריון לפי מספר שופטים','שריון זמני','שריון בידי הממשלה'],'שריון עניני קובע דרך שינוי (חוק יסוד), ולא רוב. שריון לפי מספר שופטים, שריון זמני ושריון בידי הממשלה אינם סוגי שריון מוכרים.'),
Q('מהו עניין "שימוש לרעה בסמכות המכוננת"?','התערבות בחוק יסוד שפוגע בגרעין הזהות החוקתית',['פסילת חוק רגיל בלבד','ביטול חוק יסוד כל אימת שנחקק ברוב מצומצם','הענקת סמכות חקיקה לבג"ץ'],'הדוקטרינה מתירה ביקורת מצומצמת על חוקי יסוד במקרים קיצוניים. אין כוונה לפסול כל חוק יסוד שנחקק ברוב מצומצם, ואין היא נותנת לבג"ץ סמכות חקיקה.'),
Q('בג"ץ 5658/23 פסל:','תיקון לחוק יסוד: השפיטה שצמצם את עילת הסבירות',['חוק יסוד: הלאום','חוק גל','חוק טל'],'בפרשה נפסל תיקון לחוק יסוד: השפיטה. חוק הלאום נדחתה העתירה נגדו, חוק גל לא נפסל, ובחוק טל דובר בשוויון.'),
Q('מה נקבע בעתירות נגד חוק יסוד: הלאום (2021)?','נדחו העתירות בהרכב מורחב',['החוק נפסל מיד','החוק בוטל חלקית','נקבע שחוק יסוד אינו ניתן לביקורת כלל'],'העתירות נדחו, ולא נקבע שחוק היסוד כולו חסין. פסילה מיידית, ביטול חלקי או חסינות מוחלטת מביקורת אינם תוצאת הפסק.'),
Q('מה התפקיד של הכותרת "חוק יסוד" לפי המבחן הצורני?','סימון כוונת הכנסת לפעול בכובע המכונן',['הענקת תוקף למשך 4 שנים','הגבלת סמכות בג"ץ','קביעת רוב מיוחד אוטומטי'],'הכותרת מסמנת כוונה לחקיקה חוקתית. היא אינה מגבילה זמן, ואינה קובעת רוב מיוחד אוטומטית.'),
Q('מי רשאי לשנות חוק יסוד לא משוריין, לפי הגישה השלטת?','הכנסת בחוק יסוד (ברוב רגיל)',['הכנסת בחוק רגיל','בג"ץ','הממשלה בתקנות'],'חוק יסוד משתנה בחוק יסוד, ללא דרישת רוב מיוחד אם אין שריון. חוק רגיל אינו מספיק, ובג"ץ והממשלה אינם מוסמכים.'),
Q('מהי ההיררכיה הנכונה?','חוק יסוד, חוק, תקנות, החלטה מנהלית',['חוק, חוק יסוד, תקנות, החלטה','תקנות, חוק, חוק יסוד','החלטה מנהלית, חוק, חוק יסוד'],'ההיררכיה יורדת מחוקי היסוד לחוק, לתקנות ולהחלטות מנהליות. כל סדר אחר שגוי.'),
Q('מה נכון לגבי חוק יסוד: כבוד האדם וחירותו?','אין בו שריון כללי של תוכן הזכויות',['הוא משוריין ברוב של 80','הוא בטל כשחוק רגיל סותר אותו','הוא אינו עליון'],'לפי הידוע אין שריון כללי של תוכנו, אך הוא עדיין עליון על חוק רגיל. אין בו שריון ברוב 80, והוא עליון.'),
]
