EXTRA_E={1: ' אין חובה לפרסם או לפסוק כדי להפוך הוראה למשוריינת; כל מה שקובע הוא המחסום הפרלמנטרי שמקשה על שינוי ההוראה.', 5: ' הסעיף נועד להבטיח יציבות ופשרה פוליטית, ולכן אינו נוגע לביקורת שיפוטית או לאיסור פגיעה בקניין שמופיע בסעיף אחר.', 6: ' כלומר ההגנה היא מפני פסילה בלבד, ולא פטור מפרשנות בהתאם לערכי חוק היסוד, ודין ישן לא פג וגם לא נפסל אוטומטית.', 7: ' מה שקובע הוא מועד התיקון, שהוא אחרי 1992, ולכן ההגנה על החוק הישן לא עוברת לתיקון, ובכל זאת אין בטלות מראש.', 8: ' הבחנה זו חשובה כי היא קובעת איזה מבחן חל: מבחן פסקת ההגבלה לפגיעה, ומבחן הרוב להוראה משוריינת.', 9: ' הקביעה נשענת על שריון פורמלי של ס׳ 4 לחוק יסוד: הכנסת ולא על כך שהחוק לא היה הוגן, ולכן ההכרעה היא בשל ההליך.', 10: ' בדיקת השם בלבד מספיקה כאן: חוק שנקרא "חוק" ללא התואר "יסוד" נחשב חוק רגיל, גם אם הוא חשוב מאוד.', 11: ' ההבדל מהשריון הפורמלי הוא שהדרישה כאן נוגעת לסוג החקיקה (חוק יסוד) ולא למספר הקולות הנדרש בכנסת.', 13: ' זו הפרשה הראשונה שבה בית המשפט ביטל תיקון בחוק יסוד, ולכן היא שונה מפרשות שבהן נדחו העתירות.', 14: ' הדחייה לא פירושה חסינות מוחלטת של חוק יסוד, אלא שהעתירות לא עמדו בתנאי התערבות במקרה זה.', 15: ' הכותרת מבטאת כוונה, אך אינה קובעת בעצמה רוב מיוחד, אורך תוקף, או סמכות מיוחדת לבית המשפט.', 16: ' בלי שריון מיוחד אפשר לשנות חוק יסוד ברוב רגיל, אבל רק בדרך של חוק יסוד ולא בחוק רגיל, מה שמבטא את מעמדו העליון.', 17: ' הסדר הנורמות קובע איזו נורמה גוברת בעת סתירה, וכל נורמה נתונה לביקורת מול זו שמעליה, ולכן סדר הפוך שגוי.', 18: ' אין בכך כדי לפגוע בעליונותו, שנובעת מהמבחן הצורני ולא מהשריון, והוא נחשב חוק יסוד גם בלי שריון כללי.'}
for _i,_t in EXTRA_E.items(): QS[_i]['e']+=_t
SUM[-1:-1]=['<h3>3.7 שינוי חוק יסוד: מי רשאי</h3>', '<p>הכלל המקובל הוא ש<b>חוק יסוד משתנה בחוק יסוד</b>. חוק רגיל אינו יכול לתקן או לבטל הוראה בחוק יסוד, גם אם נתקבל ברוב גדול. מכאן נגזרת גם הבעיה של "הוראות שעה" בחוקי יסוד, שבהן הכנסת משעה זמנית את תוקף הוראה: הן נעשות בחוק יסוד עצמו. מבחינת מבחן, כשמוצג חוק רגיל הסותר חוק יסוד, יש לשאול תחילה האם נעשה ניסיון לשנות את חוק היסוד בעקיפין, כי אז תתעורר שאלת השריון, או שמדובר רק בפגיעה בזכות שנבחנת בפסקת ההגבלה.</p>']
QS.append(Q('איזה כלל מתאר נכון את שינוי חוק יסוד?','חוק יסוד משתנה בחוק יסוד',['חוק יסוד משתנה בחוק רגיל ברוב מוחלט','חוק יסוד משתנה בהחלטת ממשלה','חוק יסוד משתנה בפסיקת בג"ץ בלבד'],'הכלל הוא שחוק יסוד מתוקן רק בחוק יסוד, גם אם קיים שריון וגם אם אינו קיים. חוק רגיל, אפילו ברוב גדול, אינו מספיק; והממשלה או בג"ץ אינם יכולים לשנות את נוסח חוק היסוד.'))
